Import ListNotations.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Open Scope Z_scope.

(* [comment removed for export] *)
Definition HUF_TABLELOG_MAX : Z := 12.
Definition HUF_WORKSPACE_SIZE : Z := 8704.                 (* [comment removed for export] *)
Definition HUF_flags_optimalDepth : Z := 2.
Definition HUF_flags_preferRepeat : Z := 4.
Definition HUF_flags_suspectUncompressible : Z := 8.
Definition HUF_flags_disableAsm : Z := 16.
Definition HUF_flags_disableFast : Z := 32.

(* [comment removed for export] *)
Definition DT_BYTES (mtl : Z) : Z := 4 * (1 + 2 ^ mtl).

(* [comment removed for export] *)
Record huf_params : Type := mkHP {
  hp_streams : Z;     (* [comment removed for export] *)
  hp_symbols : Z;     (* [comment removed for export] *)
  hp_flags : Z;
  hp_dbuf : Z;        (* [comment removed for export] *)
  hp_mtl : Z;         (* [comment removed for export] *)
  hp_rest : Z         (* [comment removed for export] *)
}.

Definition flag_of (c v : Z) : Z := if c =? 0 then 0 else v.

Definition huf_draws (pl : list Z) (n : Z) : huf_params :=
  let '(streams, s1) := int32Range pl n 0 1 in
  let '(symbols, s2) := int32Range pl s1 0 1 in
  let '(f1, s3) := int32Range pl s2 0 1 in
  let '(f2, s4) := int32Range pl s3 0 1 in
  let '(f3, s5) := int32Range pl s4 0 1 in
  let '(f4, s6) := int32Range pl s5 0 1 in
  let '(f5, s7) := int32Range pl s6 0 1 in
  let flags := flag_of f1 HUF_flags_optimalDepth + flag_of f2 HUF_flags_preferRepeat
               + flag_of f3 HUF_flags_suspectUncompressible + flag_of f4 HUF_flags_disableAsm
               + flag_of f5 HUF_flags_disableFast in
  let '(dbs, s8) := uint32Range pl s7 0 (8 * n + 500) in
  let '(mtl, s9) := uint32Range pl s8 1 HUF_TABLELOG_MAX in
  mkHP streams symbols flags dbs mtl s9.

(* [comment removed for export] *)
Definition huf_dt_bytes (pl : list Z) : Z := DT_BYTES (hp_mtl (huf_draws pl (Zlength pl))).
Definition huf_dbuf (pl : list Z) : Z := hp_dbuf (huf_draws pl (Zlength pl)).

(* [comment removed for export] *)
Definition DBUF_MAX : Z := 8 * 2^26 + 500.          (* [comment removed for export] *)

(* [comment removed for export] *)
(* [comment removed for export] *)

Lemma int32Range_01 : forall pl size, 0 <= size ->
  let '(r, size') := int32Range pl size 0 1 in 0 <= r <= 1 /\ 0 <= size' <= size.
