  0 <= hp_streams h <= 1 /\ 0 <= hp_symbols h <= 1 /\ 0 <= hp_dbuf h <= 8 * n + 500 /\ 1 <= hp_mtl h <= HUF_TABLELOG_MAX
  /\ 0 <= hp_rest h <= n.
